begin;
select no_plan();
insert into auth.users(id,email) values ('00000000-0000-0000-0000-000000009501','spending-a@example.test'),('00000000-0000-0000-0000-000000009502','spending-b@example.test');
insert into public.profiles(id,name,age,sex,height_cm,weight_kg,units,experience,equipment,days_per_week,session_minutes,goal,week_starts_on)
values('00000000-0000-0000-0000-000000009501','Spending A',30,'female',165,65,'metric','beginner',array['none'],3,30,'maintain',0),
('00000000-0000-0000-0000-000000009502','Spending B',30,'female',165,65,'metric','beginner',array['none'],3,30,'maintain',0);
select ok(not has_function_privilege('anon','public.set_grocery_total_amount(jsonb)','execute'),'anonymous RPC denied');
select ok(not has_function_privilege('authenticated','private.set_grocery_total_amount(jsonb)','execute'),'private implementation denied');
set local role authenticated;
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000009501';
create function pg_temp.amount_intent(p_week date,p_amount jsonb,p_key text,p_revision integer default null) returns jsonb language sql as $$
  select jsonb_build_object('weekOf',p_week,'totalAmountCentavos',p_amount,'grocery',null,'calendarRevision',(select calendar_revision from public.profiles where id=auth.uid()),'expectedVersions',jsonb_build_object('groceryRevision',coalesce(p_revision,(select revision from public.grocery_lists where user_id=auth.uid() and calendar_active and week_of=p_week),0)),'idempotencyKey',p_key);
$$;
select lives_ok($$select public.set_grocery_total_amount(pg_temp.amount_intent('2026-10-18','125050','amount-create'))$$,'amount creates an empty weekly list');
select is((select total_amount_centavos from public.grocery_lists where calendar_active),125050::bigint,'amount stored as exact centavos');
select is((select count(*) from public.grocery_items),0::bigint,'amount does not generate items');
select is(public.get_nutrition_week('2026-10-18')->'grocery'->>'total_amount_centavos','125050','weekly read includes amount');
select is(public.set_grocery_total_amount(pg_temp.amount_intent('2026-10-18','125050','amount-create',0))->>'replayed','true','duplicate original intent replays');
select throws_ok($$select public.set_grocery_total_amount(pg_temp.amount_intent('2026-10-18','5','amount-create',0))$$,'P0001',null,'changed retry identity rejected');
select throws_ok($$select public.set_grocery_total_amount(pg_temp.amount_intent('2026-10-18','5','amount-stale',0))$$,'P0001',null,'stale list rejected');
select throws_ok($$select public.set_grocery_total_amount(pg_temp.amount_intent('2026-10-19','5','amount-date'))$$,'P0001',null,'misaligned week rejected');
select throws_ok($$select public.set_grocery_total_amount(pg_temp.amount_intent('2026-10-18','-1','amount-negative'))$$,'P0001',null,'negative rejected');
select throws_ok($$select public.set_grocery_total_amount(pg_temp.amount_intent('2026-10-18','1.5','amount-fraction'))$$,'P0001',null,'fractional centavos rejected');
select throws_ok($$select public.set_grocery_total_amount(pg_temp.amount_intent('2026-10-18','9007199254740992','amount-range'))$$,'P0001',null,'unsafe integer rejected');
select throws_ok($$select public.set_grocery_total_amount(pg_temp.amount_intent('2026-10-18','"25"','amount-string'))$$,'P0001',null,'numeric text rejected');
select throws_ok($$update public.grocery_lists set total_amount_centavos=5$$,'42501',null,'direct amount write denied');
select is((select total_amount_centavos from public.grocery_lists where calendar_active),125050::bigint,'failed mutations preserve the recorded amount');
select lives_ok($$select public.set_grocery_total_amount(pg_temp.amount_intent('2026-10-25','0','amount-zero'))$$,'zero saved independently in next week');
select lives_ok($$select public.set_week_start(jsonb_build_object('weekStartsOn',6,'calendarRevision',1,'expectedRevision',(select revision from public.profiles where id=auth.uid()),'idempotencyKey','amount-saturday'))$$,'Sunday to Saturday regroup');
select is((select total_amount_centavos from public.grocery_lists where calendar_active and week_of='2026-10-17'),125050::bigint,'amount follows former start date');
select is((select total_amount_centavos from public.grocery_lists where calendar_active and week_of='2026-10-24'),0::bigint,'explicit zero is carried');
select is((select total_amount_carried_from_week from public.grocery_lists where calendar_active and week_of='2026-10-17'),'2026-10-18'::date,'carried origin visible');
select is((select count(*) from public.grocery_lists where calendar_active and total_amount_centavos=125050),1::bigint,'amount transferred once');
select is((select entry->>'total_amount_centavos' from public.calendar_transitions t cross join lateral jsonb_array_elements(t.source_groceries) entry where user_id=auth.uid() and entry->>'week_of'='2026-10-18'),'125050','source amount retained in transition audit');
select lives_ok($$select public.set_grocery_total_amount(pg_temp.amount_intent('2026-10-17','250000','amount-reviewed'))$$,'explicit review replaces carried amount');
select is((select total_amount_carried_from_week from public.grocery_lists where calendar_active and week_of='2026-10-17'),null::date,'explicit save clears amount review marker');
select lives_ok($$select public.set_week_start(jsonb_build_object('weekStartsOn',0,'calendarRevision',2,'expectedRevision',(select revision from public.profiles where id=auth.uid()),'idempotencyKey','amount-sunday'))$$,'Saturday back to Sunday');
select is((select total_amount_centavos from public.grocery_lists where calendar_active and week_of='2026-10-11'),250000::bigint,'latest active amount carried back without resurrecting inactive destination total');
select lives_ok($$select public.set_grocery_total_amount(pg_temp.amount_intent('2026-10-11','null','amount-clear'))$$,'blank clears the recorded amount');
select is((select total_amount_centavos from public.grocery_lists where calendar_active and week_of='2026-10-11'),null::bigint,'cleared amount remains null');
select lives_ok($$select public.set_week_start(jsonb_build_object('weekStartsOn',6,'calendarRevision',3,'expectedRevision',(select revision from public.profiles where id=auth.uid()),'idempotencyKey','amount-saturday-again'))$$,'repeated preference change');
select is((select total_amount_centavos from public.grocery_lists where calendar_active and week_of='2026-10-10'),null::bigint,'null is retained during regroup');
select is((select count(*) from public.grocery_lists where calendar_active and total_amount_centavos=0),1::bigint,'zero appears once after repeated transitions');
select throws_ok($$select public.set_grocery_total_amount(pg_temp.amount_intent('2026-10-10','1','old-calendar')||'{"calendarRevision":1}')$$,'P0001',null,'stale calendar rejected');
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000009502';
select is((select count(*) from public.grocery_lists),0::bigint,'cross-account lists denied');
select lives_ok($$select public.set_grocery_total_amount(pg_temp.amount_intent('2026-10-18','999','amount-other')||'{"userId":"00000000-0000-0000-0000-000000009501"}')$$,'caller owns new list regardless of supplied user ID');
select is((select total_amount_centavos from public.grocery_lists),999::bigint,'only caller amount is visible');
set local role anon;
select throws_ok($$select public.set_grocery_total_amount('{}')$$,'42501',null,'anonymous invocation denied');
reset role;
select is((select count(*) from public.grocery_lists where user_id='00000000-0000-0000-0000-000000009501' and calendar_active and total_amount_centavos=999),0::bigint,'other caller cannot write owner data');
select * from finish();
rollback;
